def fish_svg_box(svg: str, w: int = 180, h: int = 90) -> str:
    """Affiche un SVG poisson dans une boite w×h pixels, aspect ratio préservé.
    Solution au problème de tailles hétérogènes : chaque poisson a son viewBox
    propre (240×80, 220×130, 220×200, 280×35...). On injecte le SVG brut dans
    une balise <svg> de taille fixe avec preserveAspectRatio=xMidYMid meet.
    """
    import re as _re
    # Extraire le viewBox du SVG source
    vb = _re.search(r'viewBox=["\'"]([^"\'"]+)["\'"]', svg)
    viewbox = vb.group(1) if vb else '0 0 100 100'
    # Extraire le contenu intérieur du SVG (tout sauf la balise <svg ...>)
    inner = _re.sub(r'^<svg[^>]*>', '', svg, count=1).rstrip()
    inner = _re.sub(r'</svg>\s*$', '', inner)
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" '
        f'width="{w}" height="{h}" '
        f'viewBox="{viewbox}" '
        f'preserveAspectRatio="xMidYMid meet">'
        f'{inner}</svg>'
    )


def icon_box(svg: str, size: int = 36) -> str:
    """Affiche un émoji matériel/appât/météo/mer dans une boîte carrée size×size."""
    import re as _re
    vb = _re.search(r'viewBox=["\'"]([^"\'"]+)["\'"]', svg)
    viewbox = vb.group(1) if vb else '0 0 100 100'
    inner = _re.sub(r'^<svg[^>]*>', '', svg, count=1).rstrip()
    inner = _re.sub(r'</svg>\s*$', '', inner)
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" '
        f'width="{size}" height="{size}" '
        f'viewBox="{viewbox}" '
        f'preserveAspectRatio="xMidYMid meet">'
        f'{inner}</svg>'
    )

